describe('Modal Escape Key Closure', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');
  });

  it('should close modal when Escape key is pressed', () => {
    cy.get('body').type('{esc}');
    cy.get('[data-testid="modal"]').should('not.be.visible');
  });

  it('should close modal when Escape key is pressed multiple times', () => {
    cy.get('body').type('{esc}');
    cy.get('[data-testid="modal"]').should('not.be.visible');

    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="modal"]').should('be.visible');

    cy.get('body').type('{esc}{esc}');
    cy.get('[data-testid="modal"]').should('not.be.visible');
  });

  it('should not close modal when Escape key is pressed on disabled modal', () => {
    cy.get('[data-testid="modal"]').should('have.attr', 'data-closeable', 'true');
    cy.get('[data-testid="modal"]').invoke('attr', 'data-closeable', 'false');

    cy.get('body').type('{esc}');
    cy.get('[data-testid="modal"]').should('be.visible');
  });

  it('should close modal and restore focus to trigger button', () => {
    cy.get('[data-testid="open-modal-button"]').should('have.focus').blur();
    cy.get('body').type('{esc}');
    cy.get('[data-testid="modal"]').should('not.be.visible');
    cy.get('[data-testid="open-modal-button"]').should('have.focus');
  });

  it('should close nested modal with Escape key', () => {
    cy.get('[data-testid="open-nested-modal-button"]').click();
    cy.get('[data-testid="nested-modal"]').should('be.visible');

    cy.get('body').type('{esc}');
    cy.get('[data-testid="nested-modal"]').should('not.be.visible');
    cy.get('[data-testid="modal"]').should('be.visible');
  });

  it('should not close modal when Escape key is pressed inside input field with stopPropagation', () => {
    cy.get('[data-testid="modal-input"]').type('{esc}');
    cy.get('[data-testid="modal"]').should('be.visible');
  });
});
